lemma rank_lt_of_mem_simplicialInitSeg {n : ℕ} {k : ℕ} {x : Cube n}
    (hx : x ∈ simplicialInitSeg n k) :
    rank x < k

lemma downwardClosed_eq_initSeg {n : ℕ} {S : Finset (Cube n)}
    (hS : ∀ x y, simplicialLe x y → y ∈ S → x ∈ S) :
    S = simplicialInitSeg n S.card

lemma upShadow_eq_upperLayerShadow_of_uniform {N r : ℕ} {A : Finset (Cube N)}
    (hA : ∀ x ∈ A, x.card = r) :
    Finset.upShadow A = upperLayerShadow N r A

lemma upperLayerShadow_card_eq_shadow_compls {N r : ℕ} {A : Finset (Cube N)}
    (hA : ∀ x ∈ A, x.card = r) :
    (upperLayerShadow N r A).card = (Finset.shadow Aᶜˢ).card

lemma card_le_choose_of_uniform {N r : ℕ} {A : Finset (Cube N)}
    (hA : ∀ x ∈ A, x.card = r) :
    A.card ≤ Nat.choose N r

lemma coordinateUp_card_eq {N : ℕ} {i : Fin N} {A A' : Finset (Cube N)}
    (hA : IsCoordinateUp i A A') :
    A'.card = A.card

lemma coordinateDown_card_eq {N : ℕ} {i : Fin N} {B B' : Finset (Cube N)}
    (hB : IsCoordinateDown i B B') :
    B'.card = B.card

lemma coordinateUp_neighborhood_card_le {N : ℕ} {i : Fin N} {A A' : Finset (Cube N)}
    (hA : IsCoordinateUp i A A') :
    (neighborhood 1 A').card ≤ (neighborhood 1 A).card

lemma coordinateDown_neighborhood_card_le {N : ℕ} {i : Fin N} {B B' : Finset (Cube N)}
    (hB : IsCoordinateDown i B B') :
    (neighborhood 1 B').card ≤ (neighborhood 1 B).card

