          rw [ Nat.mod_eq_sub_mod hxy_ge_h ];
          rw [ Nat.mod_eq_of_lt ( by omega ) ];
        contrapose! hA;
        simp_all +decide only [add_tsub_cancel_of_le, ge_iff_le, ne_eq, IsTripleFree, not_not];
