      simp_all +decide only [Xset, mem_filter, mem_Ico, Yset, and_self, true_and, not_not];
      exact ⟨ a, ha₁.2, b, hb₁.2, h, hh, by omega, by omega, by omega, by ring_nf at *; aesop ⟩;
